"""Legacy EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


def _is_blank(value: Any) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def _fixed(value: Any, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    if _is_blank(value):
        amount = Decimal(0)
    else:
        try:
            amount = Decimal(str(value))
        except (InvalidOperation, ValueError) as exc:
            raise ValueError("ANN_REV must be a finite decimal value") from exc

    if not amount.is_finite():
        raise ValueError("ANN_REV must be a finite decimal value")

    cents = (amount * Decimal(100)).quantize(
        Decimal("1"), rounding=ROUND_HALF_UP
    )
    integer_cents = int(cents)

    if integer_cents < 0:
        rendered = "-" + str(abs(integer_cents)).zfill(width - 1)
    else:
        rendered = str(integer_cents).zfill(width)

    if len(rendered) > width:
        raise ValueError(f"ANN_REV cents exceed the {width}-character field")

    return rendered


def format_account(row: dict) -> str:
    """Build one 77-character legacy EXPORT_ACCT record."""
    account_id = _fixed(row.get("ACCT_ID", ""), 10)
    account_name = _fixed(row.get("ACCT_NM", ""), 40)
    region_code = _fixed(row.get("REGION_CD", ""), 3)
    annual_revenue = _zpad_cents(row.get("ANN_REV", ""), 15)

    credit_hold_value = row.get("CRED_HOLD", "")
    credit_hold = "N" if _is_blank(credit_hold_value) else str(credit_hold_value)
    if len(credit_hold) != 1:
        raise ValueError("CRED_HOLD must be one character")

    create_date_value = row.get("CREATE_DT", "")
    create_date = "00000000" if _is_blank(create_date_value) else str(create_date_value)
    if len(create_date) != 8:
        raise ValueError("CREATE_DT must be an 8-character YYYYMMDD value")

    record = (
        account_id
        + account_name
        + region_code
        + annual_revenue
        + credit_hold
        + create_date
    )

    if len(record) != 77:
        raise ValueError("EXPORT_ACCT record must be exactly 77 characters")

    return record
